91	    static final long MAX_OWNERS_PER_DAY = 100;
92	
93	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
94	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
